29. import static java.util.stream.Collectors.toList;
30. 
31. final class TestCase implements io.cucumber.plugin.event.TestCase {
32. 
33.     private final Pickle pickle;
34.     private final List<PickleStepTestStep> testSteps;
35.     private final ExecutionMode executionMode;
36.     private final List<HookTestStep> beforeHooks;
37.     private final List<HookTestStep> afterHooks;
38.     private final UUID id;
39. 
40.     TestCase(
41.             UUID id, List<PickleStepTestStep> testSteps,
42.             List<HookTestStep> beforeHooks,
43.             List<HookTestStep> afterHooks,
44.             Pickle pickle,
45.             boolean dryRun
46.     ) {
47.         this.id = id;
48.         this.testSteps = testSteps;
49.         this.beforeHooks = beforeHooks;
50.         this.afterHooks = afterHooks;
51.         this.pickle = pickle;
52.         this.executionMode = dryRun ? DRY_RUN : RUN;
53.     }
54. 
55.     private static io.cucumber.messages.types.Group makeMessageGroup(
56.             Group group
57.     ) {
58.         return new io.cucumber.messages.types.Group(
59.             group.getChildren().stream()
60.                     .map(TestCase::makeMessageGroup)
61.                     .collect(toList()),
62.             (long) group.getStart(),
63.             group.getValue());
64.     }
65. 
66.     void run(EventBus bus) {
67.         ExecutionMode nextExecutionMode = this.executionMode;
68.         emitTestCaseMessage(bus);
69. 
70.         Instant start = bus.getInstant();
71.         UUID executionId = bus.generateId();
72.         emitTestCaseStarted(bus, start, executionId);
73. 
74.         TestCaseState state = new TestCaseState(bus, executionId, this);
75. 
76.         for (HookTestStep before : beforeHooks) {
77.             nextExecutionMode = before
78.                     .run(this, bus, state, executionMode)
79.                     .next(nextExecutionMode);
80.         }
81. 
82.         for (PickleStepTestStep step : testSteps) {
83.             nextExecutionMode = step
84.                     .run(this, bus, state, nextExecutionMode)
85.                     .next(nextExecutionMode);
86.         }
87. 
88.         for (HookTestStep after : afterHooks) {
89.             nextExecutionMode = after
90.                     .run(this, bus, state, executionMode)
91.                     .next(nextExecutionMode);
92.         }
93. 
94.         Instant stop = bus.getInstant();
95.         Duration duration = Duration.between(start, stop);
96.         Status status = Status.valueOf(state.getStatus().name());
97.         Result result = new Result(status, duration, state.getError());
98.         emitTestCaseFinished(bus, executionId, stop, result);
99.     }
