137.         List<TestStep> testSteps = new ArrayList<>(beforeHooks);
138.         for (PickleStepTestStep step : this.testSteps) {
139.             testSteps.addAll(step.getBeforeStepHookSteps());
140.             testSteps.add(step);
141.             testSteps.addAll(step.getAfterStepHookSteps());
142.         }
143.         testSteps.addAll(afterHooks);
144.         return testSteps;
145.     }
146. 
