157.     private void emitTestCaseMessage(EventBus bus) {
158.         Envelope envelope = Envelope.of(new io.cucumber.messages.types.TestCase(
159.             id.toString(),
160.             pickle.getId(),
161.             getTestSteps()
162.                     .stream()
163.                     .map(this::createTestStep)
164.                     .collect(toList())));
165.         bus.send(envelope);
166.     }
167. 
168.     private io.cucumber.messages.types.TestStep createTestStep(TestStep pluginTestStep) {
169.         // public TestStep(String hookId, String id, String pickleStepId,
170.         // List<String> stepDefinitionIds, List<StepMatchArgumentsList>
171.         // stepMatchArgumentsLists) {
172.         String id = pluginTestStep.getId().toString();
173.         String hookId = null;
174.         String pickleStepId = null;
175.         List<StepMatchArgumentsList> stepMatchArgumentsLists = null;
176.         List<String> stepDefinitionIds = null;
177. 
178.         if (pluginTestStep instanceof HookTestStep) {
179.             HookTestStep hookTestStep = (HookTestStep) pluginTestStep;
180.             HookDefinitionMatch definitionMatch = hookTestStep.getDefinitionMatch();
181.             CoreHookDefinition hookDefinition = definitionMatch.getHookDefinition();
182.             hookId = hookDefinition.getId().toString();
183.         } else if (pluginTestStep instanceof PickleStepTestStep) {
184.             PickleStepTestStep pickleStep = (PickleStepTestStep) pluginTestStep;
185.             pickleStepId = pickleStep.getStep().getId();
186.             stepMatchArgumentsLists = singletonList(getStepMatchArguments(pickleStep));
187.             StepDefinition stepDefinition = pickleStep.getDefinitionMatch().getStepDefinition();
188.             if (stepDefinition instanceof CoreStepDefinition) {
189.                 CoreStepDefinition coreStepDefinition = (CoreStepDefinition) stepDefinition;
190.                 stepDefinitionIds = singletonList(coreStepDefinition.getId().toString());
191.             }
192.         }
193. 
194.         return new io.cucumber.messages.types.TestStep(hookId, id, pickleStepId, stepDefinitionIds,
195.             stepMatchArgumentsLists);
196.     }
197. 
198.     public StepMatchArgumentsList getStepMatchArguments(PickleStepTestStep pickleStep) {
199.         return new StepMatchArgumentsList(
200.             pickleStep.getDefinitionArgument().stream()
201.                     .map(arg -> new StepMatchArgument(makeMessageGroup(arg.getGroup()), arg.getParameterTypeName()))
202.                     .collect(Collectors.toList()));
203.     }
